create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,username text unique,display_name text not null default 'New member',avatar_url text,about text default 'Hey there! I am using King Chat.',phone text,last_seen_at timestamptz,is_online boolean default false,created_at timestamptz default now());
create table if not exists public.conversations(id uuid primary key default gen_random_uuid(),kind text not null default 'direct' check(kind in ('direct','group','channel')),title text,photo_url text,created_by uuid references auth.users(id),created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.conversation_members(conversation_id uuid references public.conversations(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,role text default 'member',joined_at timestamptz default now(),last_read_at timestamptz,primary key(conversation_id,user_id));
create table if not exists public.messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations(id) on delete cascade,sender_id uuid references auth.users(id),body text,message_type text default 'text' check(message_type in ('text','image','video','audio','file','location','system')),attachment_url text,reply_to uuid references public.messages(id),edited_at timestamptz,deleted_at timestamptz,created_at timestamptz default now(),check(body is not null or attachment_url is not null or message_type='system'));
create index if not exists messages_conversation_created_idx on public.messages(conversation_id,created_at desc);
create table if not exists public.reactions(message_id uuid references public.messages(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,emoji text not null,created_at timestamptz default now(),primary key(message_id,user_id,emoji));
create table if not exists public.status_updates(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,media_url text,caption text,created_at timestamptz default now(),expires_at timestamptz default now()+interval '24 hours');
create table if not exists public.status_views(status_id uuid references public.status_updates(id) on delete cascade,viewer_id uuid references auth.users(id) on delete cascade,viewed_at timestamptz default now(),primary key(status_id,viewer_id));
create table if not exists public.call_logs(id uuid primary key default gen_random_uuid(),conversation_id uuid references public.conversations(id),caller_id uuid references auth.users(id),callee_id uuid references auth.users(id),call_type text check(call_type in ('voice','video')),status text default 'ringing',started_at timestamptz default now(),ended_at timestamptz);
create table if not exists public.device_tokens(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,token text unique not null,platform text default 'android',created_at timestamptz default now());
create or replace function public.is_conversation_member(cid uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.conversation_members where conversation_id=cid and user_id=auth.uid()) $$;
alter table public.profiles enable row level security; alter table public.conversations enable row level security; alter table public.conversation_members enable row level security; alter table public.messages enable row level security; alter table public.reactions enable row level security; alter table public.status_updates enable row level security; alter table public.status_views enable row level security; alter table public.call_logs enable row level security; alter table public.device_tokens enable row level security;
create policy "profile read authenticated" on public.profiles for select to authenticated using(true);
create policy "profile self insert" on public.profiles for insert to authenticated with check(id=auth.uid());
create policy "profile self update" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy "conversation members read" on public.conversations for select to authenticated using(public.is_conversation_member(id));
create policy "users create conversation" on public.conversations for insert to authenticated with check(created_by=auth.uid());
create policy "membership read" on public.conversation_members for select to authenticated using(public.is_conversation_member(conversation_id) or user_id=auth.uid());
create policy "membership add" on public.conversation_members for insert to authenticated with check(user_id=auth.uid() or exists(select 1 from public.conversations c where c.id=conversation_id and c.created_by=auth.uid()));
create policy "messages read by members" on public.messages for select to authenticated using(public.is_conversation_member(conversation_id));
create policy "members send messages" on public.messages for insert to authenticated with check(sender_id=auth.uid() and public.is_conversation_member(conversation_id));
create policy "sender edits own messages" on public.messages for update to authenticated using(sender_id=auth.uid()) with check(sender_id=auth.uid());
create policy "member reactions" on public.reactions for all to authenticated using(exists(select 1 from public.messages m where m.id=message_id and public.is_conversation_member(m.conversation_id))) with check(user_id=auth.uid() and exists(select 1 from public.messages m where m.id=message_id and public.is_conversation_member(m.conversation_id)));
create policy "active status visible" on public.status_updates for select to authenticated using(expires_at>now());
create policy "publish own status" on public.status_updates for insert to authenticated with check(user_id=auth.uid());
create policy "delete own status" on public.status_updates for delete to authenticated using(user_id=auth.uid());
create policy "status views readable" on public.status_views for select to authenticated using(viewer_id=auth.uid() or exists(select 1 from public.status_updates s where s.id=status_id and s.user_id=auth.uid()));
create policy "mark status viewed" on public.status_views for insert to authenticated with check(viewer_id=auth.uid());
create policy "read own call logs" on public.call_logs for select to authenticated using(caller_id=auth.uid() or callee_id=auth.uid());
create policy "create call log" on public.call_logs for insert to authenticated with check(caller_id=auth.uid());
create policy "update participant call" on public.call_logs for update to authenticated using(caller_id=auth.uid() or callee_id=auth.uid()) with check(caller_id=auth.uid() or callee_id=auth.uid());
create policy "manage own device tokens" on public.device_tokens for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('chat-media','chat-media',false,52428800,array['image/jpeg','image/png','image/webp','video/mp4','audio/mpeg','audio/mp4','application/pdf']) on conflict(id) do nothing;
create policy "upload own chat media" on storage.objects for insert to authenticated with check(bucket_id='chat-media' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "read own chat media" on storage.objects for select to authenticated using(bucket_id='chat-media' and (storage.foldername(name))[1]=auth.uid()::text);